import { requireAdminPage } from "@/lib/admin/page-auth";
import { getAdminControl } from "@/lib/admin/queries";
import { SendingControls } from "@/components/admin/sending-controls";
import { AdminNotice } from "@/components/admin/common";
export default async function ControlsPage() {
  await requireAdminPage();
  let control;
  try {
    control = await getAdminControl();
  } catch {
    return <AdminNotice />;
  }
  return (
    <>
      <h1 className="text-3xl font-semibold">Sending controls</h1>
      <p>
        Global sending is{" "}
        <strong>{control.sendingEnabled ? "enabled" : "disabled"}</strong>.
      </p>
      <p>
        Disabling sending blocks new claims. Billing callbacks, cancellation,
        export, deletion, and support remain available.
      </p>
      <SendingControls {...control} />
    </>
  );
}
